#include <vector>
#include <queue>
#include <unordered_set>

class Solution {
public:
    int minFlips(std::vector<std::vector<int>>& mat) {
        int m = mat.size(), n = mat[0].size();
        int start = 0;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (mat[r][c]) start |= (1 << (r * n + c));
            }
        }
        if (start == 0) return 0;
        std::queue<std::pair<int, int>> q;
        q.push({start, 0});
        std::vector<bool> seen(1 << (m * n), false);
        seen[start] = true;
        int dirs[5][2] = {{0, 0}, {1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!q.empty()) {
            auto [state, steps] = q.front();
            q.pop();
            for (int r = 0; r < m; ++r) {
                for (int c = 0; c < n; ++c) {
                    int nxt = state;
                    for (auto& d : dirs) {
                        int nr = r + d[0], nc = c + d[1];
                        if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                            nxt ^= (1 << (nr * n + nc));
                        }
                    }
                    if (nxt == 0) return steps + 1;
                    if (!seen[nxt]) {
                        seen[nxt] = true;
                        q.push({nxt, steps + 1});
                    }
                }
            }
        }
        return -1;
    }
};

import java.util.*;

class Solution {
    public int minFlips(int[][] mat) {
        int m = mat.length, n = mat[0].length;
        int start = 0;
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (mat[r][c] == 1) start |= (1 << (r * n + c));
            }
        }
        if (start == 0) return 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{start, 0});
        boolean[] seen = new boolean[1 << (m * n)];
        seen[start] = true;
        int[][] dirs = {{0, 0}, {1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int state = cur[0], steps = cur[1];
            for (int r = 0; r < m; r++) {
                for (int c = 0; c < n; c++) {
                    int nxt = state;
                    for (int[] d : dirs) {
                        int nr = r + d[0], nc = c + d[1];
                        if (nr >= 0 && nr < m && nc >= 0 && nc < n) {
                            nxt ^= (1 << (nr * n + nc));
                        }
                    }
                    if (nxt == 0) return steps + 1;
                    if (!seen[nxt]) {
                        seen[nxt] = true;
                        q.offer(new int[]{nxt, steps + 1});
                    }
                }
            }
        }
        return -1;
    }
}

